                while dq:
                    x,y=dq.popleft()
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<R and 0<=ny<C and i[nx][ny]==1 and (nx,ny) not in seen:
