                rs=[x for x,_ in cells]; cs=[y for _,y in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                h,w=r1-r0+1,c1-c0+1
                ring=all(i[x][y]==1 for x in (r0,r1) for y in range(c0,c1+1)) and all(i[x][y]==1 for y in (c0,c1) for x in range(r0,r1+1))
                if not ring or h<3 or w<3: continue
